class Solution {
    public:
        ListNode* oddEvenList(ListNode* &head) {
            ListNode* dummyOdd = new ListNode();
            ListNode* dummyEven = new ListNode();
            ListNode* odd = dummyOdd;
            ListNode* even = dummyEven;
