            while (temp != nullptr) {
                ListNode* newNode = new ListNode(temp->data);
                if (cnt % 2 == 0) {
                    even->next = newNode;
                    even = even->next;
                } else {
                    odd->next = newNode;
                    odd = odd->next;
                }
                temp = temp->next;
                cnt++;
            }

            odd->next = dummyEven->next;
            return dummyOdd->next;
        }
};
